#!/usr/bin/env bash
set -euo pipefail

# Project / benchmark paths
MEMORYCARD_ROOT="${MEMORYCARD_ROOT:-/path/to/MemoryCard}"
LMMS_EVAL_ROOT="${LMMS_EVAL_ROOT:-/path/to/lmms-eval}"

# Model paths
PRETRAINED="${PRETRAINED:-/path/to/Qwen3-VL-8B-Instruct}"
LONGCLIP_REPO="${LONGCLIP_REPO:-/path/to/Long-CLIP-main}"
LONGCLIP_MODEL="${LONGCLIP_MODEL:-/path/to/longclip-L.pt}"

# Memory Card path generated by Step 2
CARDS_ROOT="${CARDS_ROOT:-/path/to/output/videomme_memory/cards}"

# Output path
OUTPUT_PATH="${OUTPUT_PATH:-/path/to/output/eval_logs}"
LOG_SUFFIX="${LOG_SUFFIX:-qwen3_vl_w_cards_videomme}"

# lmms-eval settings
export CUDA_VISIBLE_DEVICES="${CUDA_VISIBLE_DEVICES:-0}"
NUM_PROCESSES="${NUM_PROCESSES:-1}"
MAIN_PORT="${MAIN_PORT:-8001}"
TASK_NAME="${TASK_NAME:-videomme}"
BATCH_SIZE="${BATCH_SIZE:-1}"

MAX_NUM_FRAMES="${MAX_NUM_FRAMES:-128}"
SAMPLE_FRAMES="${SAMPLE_FRAMES:-8}"
HIGH_FRAMES="${HIGH_FRAMES:-4}"
MID_FRAMES="${MID_FRAMES:-8}"
LOW_FRAMES="${LOW_FRAMES:-32}"
SKIP_NO_CARDS="${SKIP_NO_CARDS:-true}"

DEBUG_DUMP_DIR="${DEBUG_DUMP_DIR:-${OUTPUT_PATH}/debug_retrieval_cards/${LOG_SUFFIX}}"
DEBUG_DUMP_EVERY="${DEBUG_DUMP_EVERY:-1}"

export HF_DATASETS_OFFLINE="${HF_DATASETS_OFFLINE:-0}"
export HF_HUB_OFFLINE="${HF_HUB_OFFLINE:-0}"
export TRANSFORMERS_OFFLINE="${TRANSFORMERS_OFFLINE:-0}"

check_path() {
  local name="$1"
  local value="$2"
  if [[ -z "${value}" || "${value}" == /path/to/* ]]; then
    echo "[ERROR] ${name} is not set: ${value}" >&2
    echo "Please edit the path section at the top of this script." >&2
    exit 1
  fi
}

check_path "MEMORYCARD_ROOT" "${MEMORYCARD_ROOT}"
check_path "LMMS_EVAL_ROOT" "${LMMS_EVAL_ROOT}"
check_path "PRETRAINED" "${PRETRAINED}"
check_path "LONGCLIP_REPO" "${LONGCLIP_REPO}"
check_path "LONGCLIP_MODEL" "${LONGCLIP_MODEL}"
check_path "CARDS_ROOT" "${CARDS_ROOT}"
check_path "OUTPUT_PATH" "${OUTPUT_PATH}"

mkdir -p "${OUTPUT_PATH}"
if [[ -n "${DEBUG_DUMP_DIR}" ]]; then
  mkdir -p "${DEBUG_DUMP_DIR}"
fi

export LONGCLIP_REPO="${LONGCLIP_REPO}"
export LONGCLIP_MODEL="${LONGCLIP_MODEL}"
export PYTHONPATH="${MEMORYCARD_ROOT}:${LONGCLIP_REPO}:${PYTHONPATH:-}"

if [[ -n "${CONDA_PREFIX:-}" ]]; then
  export LD_LIBRARY_PATH="${CONDA_PREFIX}/lib:${LD_LIBRARY_PATH:-}"
fi

cd "${LMMS_EVAL_ROOT}"

cat <<INFO
==================================================
[STEP3]  lmms-eval inference with Memory Cards
LMMS_EVAL_ROOT=${LMMS_EVAL_ROOT}
PRETRAINED=${PRETRAINED}
CARDS_ROOT=${CARDS_ROOT}
LONGCLIP_REPO=${LONGCLIP_REPO}
LONGCLIP_MODEL=${LONGCLIP_MODEL}
POOL_SIZE / HIGH / MID / LOW = ${MAX_NUM_FRAMES} / ${HIGH_FRAMES} / ${MID_FRAMES} / ${LOW_FRAMES}
CUDA_VISIBLE_DEVICES=${CUDA_VISIBLE_DEVICES}
NUM_PROCESSES=${NUM_PROCESSES}
OUTPUT_PATH=${OUTPUT_PATH}
LOG_SUFFIX=${LOG_SUFFIX}
DEBUG_DUMP_DIR=${DEBUG_DUMP_DIR}
==================================================
INFO

accelerate launch \
  --num_processes "${NUM_PROCESSES}" \
  --main_process_port "${MAIN_PORT}" \
  -m lmms_eval \
  --model qwen3_vl_w_cards_videomme \
  --model_args "pretrained=${PRETRAINED},max_num_frames=${MAX_NUM_FRAMES},sample_frames=${SAMPLE_FRAMES},high_frames=${HIGH_FRAMES},mid_frames=${MID_FRAMES},low_frames=${LOW_FRAMES},cards_root=${CARDS_ROOT},skip_videos_without_cards=${SKIP_NO_CARDS},debug_dump_dir=${DEBUG_DUMP_DIR},debug_dump_every=${DEBUG_DUMP_EVERY}" \
  --task "${TASK_NAME}" \
  --batch_size "${BATCH_SIZE}" \
  --log_samples \
  --log_samples_suffix "${LOG_SUFFIX}" \
  --output_path "${OUTPUT_PATH}"
